    int minFlips(string s) {
        int n = s.size();
        string ss = s + s;
        int diff1 = 0, diff2 = 0, ans = n;

        for (int i = 0; i < 2 * n; ++i) {
            char t1 = (i % 2 == 0) ? '0' : '1';
