            }

            if (i >= n - 1) {
                ans = min({ans, diff1, diff2});
            }
        }
        return ans;
    }
};

class Solution {
    public int minFlips(String s) {
        int n = s.length();
        String ss = s + s;
        int diff1 = 0, diff2 = 0, ans = n;

        for (int i = 0; i < 2 * n; ++i) {
            char t1 = (i % 2 == 0) ? '0' : '1';
            char t2 = (i % 2 == 0) ? '1' : '0';

            if (ss.charAt(i) != t1) diff1++;
            if (ss.charAt(i) != t2) diff2++;

            if (i >= n) {
                char oldT1 = ((i - n) % 2 == 0) ? '0' : '1';
                char oldT2 = ((i - n) % 2 == 0) ? '1' : '0';
                if (ss.charAt(i - n) != oldT1) diff1--;
                if (ss.charAt(i - n) != oldT2) diff2--;
            }

            if (i >= n - 1) {
                ans = Math.min(ans, Math.min(diff1, diff2));
            }
        }
        return ans;
    }
}

