var minFlips = function(s) {
    const n = s.length;
    const ss = s + s;
    let diff1 = 0, diff2 = 0, ans = n;

    for (let i = 0; i < 2 * n; ++i) {
        const t1 = i % 2 === 0 ? '0' : '1';
        const t2 = i % 2 === 0 ? '1' : '0';

        if (ss[i] !== t1) diff1++;
        if (ss[i] !== t2) diff2++;

        if (i >= n) {
            const oldT1 = (i - n) % 2 === 0 ? '0' : '1';
            const oldT2 = (i - n) % 2 === 0 ? '1' : '0';
            if (ss[i - n] !== oldT1) diff1--;
            if (ss[i - n] !== oldT2) diff2--;
        }

        if (i >= n - 1) {
            ans = Math.min(ans, diff1, diff2);
        }
    }
    return ans;
};
